enum PaginationStatus { initial, loading, ready, loadingMore, refreshing, endOfList, error }
class PaginationState<T>{const PaginationState({this.items=const[],this.status=PaginationStatus.initial,this.nextPageToken,this.error});final List<T> items;final PaginationStatus status;final String? nextPageToken;final Object? error;PaginationState<T> copyWith({List<T>? items,PaginationStatus? status,String? nextPageToken,Object? error})=>PaginationState(items:items??this.items,status:status??this.status,nextPageToken:nextPageToken??this.nextPageToken,error:error);}
class MockPaginator<T>{MockPaginator(this.source,{this.pageSize=10});final List<T> source;final int pageSize;PaginationState<T> state=const PaginationState();Future<PaginationState<T>> loadInitial()async{state=const PaginationState(status:PaginationStatus.loading);return _page(0);}Future<PaginationState<T>> loadMore()async{if(state.status==PaginationStatus.endOfList)return state;state=state.copyWith(status:PaginationStatus.loadingMore);return _page(state.items.length);}Future<PaginationState<T>> refresh()=>loadInitial();PaginationState<T> _page(int start){final end=(start+pageSize).clamp(0,source.length) as int;final combined=start==0?source.sublist(0,end):[...state.items,...source.sublist(start,end)];return state=PaginationState(items:combined,status:end==source.length?PaginationStatus.endOfList:PaginationStatus.ready,nextPageToken:end==source.length?null:'$end');}}
